// Main Winograd F(2,3) conv1d kernel.
// Grid: (N, Cout, ceil(L_out / WINO_TILE_OUT))
// Block: (BLOCK_CIN) threads -- covers input channels, loop if needed
#define BLOCK_CIN 128

__global__ void __launch_bounds__(BLOCK_CIN, 8)
conv1d_wino_kernel(
    const float* __restrict__ input,    // [N, Cin, L_in]
    const float* __restrict__ wtrans,   // [Cout, Cin, 4] pre-transformed
    const float* __restrict__ bias,     // [Cout] or nullptr
    float* __restrict__ output,         // [N, Cout, L_out]
    int N, int Cin, int Cout,
    int L_in, int L_out, int padding
) {
    int n       = blockIdx.x;
    int oc      = blockIdx.y;
    int tile_id = blockIdx.z;

    int out_base = tile_id * WINO_TILE_OUT;
    if (out_base >= L_out) return;

    // Input positions for this tile: out_base-padding .. out_base-padding+3
    int in_base = out_base - padding; // first input sample for this tile

    // Each thread accumulates partial sums for 4 Winograd domain elements
    float s0 = 0.f, s1 = 0.f, s2 = 0.f, s3 = 0.f;

    const float* inp_n = input + n * Cin * L_in;
    const float* wt_oc = wtrans + oc * Cin * 4;

    for (int ic = threadIdx.x; ic < Cin; ic += BLOCK_CIN) {
        // Load 4 input samples with boundary check
        float d0, d1, d2, d3;
        int i0 = in_base + 0;
        int i1 = in_base + 1;
        int i2 = in_base + 2;
        int i3 = in_base + 3;
        const float* src = inp_n + ic * L_in;
        d0 = (i0 >= 0 && i0 < L_in) ? src[i0] : 0.f;
        d1 = (i1 >= 0 && i1 < L_in) ? src[i1] : 0.f;
        d2 = (i2 >= 0 && i2 < L_in) ? src[i2] : 0.f;
        d3 = (i3 >= 0 && i3 < L_in) ? src[i3] : 0.f;

        // B^T transform of input
        float v0 = d0 - d2;
        float v1 = d1 + d2;
        float v2 = d2 - d1;
        float v3 = d3 - d1;

        // Load pre-transformed weight for this (oc, ic)
        const float* wu = wt_oc + ic * 4;
        float u0 = wu[0], u1 = wu[1], u2 = wu[2], u3 = wu[3];

        s0 += v0 * u0;
        s1 += v1 * u1;
        s2 += v2 * u2;
        s3 += v3 * u3;
    }

    // Warp reduction
    for (int offset = 16; offset > 0; offset >>= 1) {
        s0 += __shfl_down_sync(0xffffffff, s0, offset);
        s1 += __shfl_down_sync(0xffffffff, s1, offset);
        s2 += __shfl_down_sync(0xffffffff, s2, offset);
        s3 += __shfl_down_sync(0xffffffff, s3, offset);
    }

    // If Cin > 32, we need shared memory reduction across warps
    __shared__ float smem[4][4]; // [4 winograd elems][max 4 warps for BLOCK_CIN=128]
    int warp_id = threadIdx.x / 32;
    int lane    = threadIdx.x % 32;
    int num_warps = (BLOCK_CIN + 31) / 32;

    if (lane == 0) {
        smem[0][warp_id] = s0;
        smem[1][warp_id] = s1;
        smem[2][warp_id] = s2;
        smem[3][warp_id] = s3;
    }
    __syncthreads();

    if (threadIdx.x == 0) {
        s0 = 0.f; s1 = 0.f; s2 = 0.f; s3 = 0.f;
        for (int w = 0; w < num_warps; w++) {
            s0 += smem[0][w];
            s1 += smem[1][w];
            s2 += smem[2][w];
            s3 += smem[3][w];
        }

        // A^T inverse transform: y0 = s0+s1+s2, y1 = s1-s2-s3
        float y0 = s0 + s1 + s2;
        float y1 = s1 - s2 - s3;

        float b = (bias != nullptr) ? bias[oc] : 0.f;

        float* out_ptr = output + n * Cout * L_out + oc * L_out;
        if (out_base < L_out)     out_ptr[out_base]     = y0 + b;
        if (out_base + 1 < L_out) out_ptr[out_base + 1] = y1 + b;
    }
}

