    float w1 = weight[oc * Cin * 3 + ic * 3 + 1];
    float w2 = weight[oc * Cin * 3 + ic * 3 + 2];

    weight_g[oc * Cin * 4 + ic * 4 + 0] = w0;
    weight_g[oc * Cin * 4 + ic * 4 + 1] = (w0 + w1 + w2) * 0.5f;
    weight_g[oc * Cin * 4 + ic * 4 + 2] = (w0 - w1 + w2) * 0.5f;
